/**
 * VK Callback API → shared channel envelope.
 *
 * The envelope is deliberately identical in shape to the Telegram one, so the
 * agent and its tools never learn which channel they are on. Adding Avito or
 * MAX later means writing another normalizer, not touching any build.
 *
 * This file is the single source of truth. It is injected verbatim into the
 * Code node of every VK workflow by sync-code-node.py — never hand-edit the
 * copy inside a workflow.json.
 */

/** VK photo size types, worst to best. Used only as a tiebreak when width is absent. */
const SIZE_RANK = ['s', 'm', 'o', 'p', 'q', 'r', 'x', 'y', 'z', 'w'];

/** Image extensions we are willing to send to OCR. A .pdf doc is not one. */
const IMAGE_EXTS = new Set(['jpg', 'jpeg', 'png', 'heic', 'webp', 'bmp']);

/**
 * Pick the largest available rendition of a VK photo.
 * VK does not guarantee `sizes` is ordered, and older payloads omit `width`.
 */
function largestPhotoUrl(photo) {
  const sizes = Array.isArray(photo && photo.sizes) ? photo.sizes : [];
  if (sizes.length === 0) return '';

  let best = null;
  for (const s of sizes) {
    if (!s || !s.url) continue;
    if (best === null) { best = s; continue; }

    const byWidth = (s.width || 0) - (best.width || 0);
    if (byWidth > 0) { best = s; continue; }
    if (byWidth === 0 && SIZE_RANK.indexOf(s.type) > SIZE_RANK.indexOf(best.type)) best = s;
  }
  return best ? best.url : '';
}

/** Lowercase extension of a VK doc, '' when absent. */
function docExt(doc) {
  if (doc && typeof doc.ext === 'string' && doc.ext) return doc.ext.toLowerCase();
  const title = (doc && doc.title) || '';
  const dot = title.lastIndexOf('.');
  return dot === -1 ? '' : title.slice(dot + 1).toLowerCase();
}

/**
 * Find the first attachment we know how to handle.
 * Order matters: a photo is a better OCR input than a doc of the same receipt,
 * and users regularly send both.
 */
function extractAttachment(attachments) {
  const list = Array.isArray(attachments) ? attachments : [];
  const none = { file_url: '', file_kind: '', audio_url: '' };

  const photo = list.find((a) => a && a.type === 'photo' && a.photo);
  if (photo) {
    const url = largestPhotoUrl(photo.photo);
    if (url) return { file_url: url, file_kind: 'photo', audio_url: '' };
  }

  const doc = list.find((a) => a && a.type === 'doc' && a.doc && a.doc.url);
  if (doc) {
    const ext = docExt(doc.doc);
    // A non-image doc still gets reported, so the caller can route it to manual
    // review with an honest reason instead of failing inside OCR.
    return {
      file_url: doc.doc.url,
      file_kind: IMAGE_EXTS.has(ext) ? 'doc' : 'doc_unsupported',
      audio_url: '',
    };
  }

  const voice = list.find((a) => a && a.type === 'audio_message' && a.audio_message);
  if (voice) {
    const am = voice.audio_message;
    const url = am.link_ogg || am.link_mp3 || '';
    if (url) return { file_url: '', file_kind: 'audio_message', audio_url: url };
  }

  return none;
}

/**
 * A stable non-zero 31-bit integer derived from a string.
 *
 * VK requires `random_id` on messages.send to be non-zero, and dedups sends
 * that repeat one. Deriving it from the event id rather than from the clock
 * means an n8n retry of the same event cannot produce a second reply.
 */
function replyRandomId(seed) {
  let h = 7;
  const s = String(seed || '');
  for (let i = 0; i < s.length; i++) h = (Math.imul(h, 31) + s.charCodeAt(i)) | 0;
  return (h >>> 0) % 2147483647 || 1; // never 0 — VK rejects it
}

/**
 * @param {object} body - the raw parsed JSON body of a VK Callback POST
 * @returns {object} the shared envelope
 */
function normalizeVkEvent(body) {
  const b = body || {};
  const msg = (b.object && b.object.message) || {};
  const att = extractAttachment(msg.attachments);

  const fromId = msg.from_id === undefined || msg.from_id === null ? '' : String(msg.from_id);
  const peerId = msg.peer_id === undefined || msg.peer_id === null ? '' : String(msg.peer_id);

  // VK's event_id is stable across its own retries; message id is not a safe
  // dedup key because a retry of the *same* delivery carries the same message.
  // Fall back to a composite only when VK omits event_id (it does for some
  // older community settings).
  const eventId = b.event_id ? String(b.event_id) : `${b.group_id || 'g'}:${msg.id || 'm'}:${msg.date || '0'}`;

  return {
    channel: 'vk',
    event_id: eventId,
    group_id: b.group_id === undefined ? '' : String(b.group_id),
    user_id: fromId,
    chat_id: peerId,
    session_key: `vk:${fromId || 'unknown'}`,
    text: typeof msg.text === 'string' ? msg.text : '',
    file_url: att.file_url,
    file_kind: att.file_kind,
    audio_url: att.audio_url,
    message_id: msg.id === undefined || msg.id === null ? '' : String(msg.id),
    ts: msg.date ? new Date(msg.date * 1000).toISOString() : new Date().toISOString(),
    reply_random_id: replyRandomId(eventId),
  };
}

// ---------------------------------------------------------------------------
// n8n glue. Everything above is injected by sync-code-node.py from the source
// named below. Do not edit it here — edit the source and re-run the sync.
//   source: builds/vk-adapter/normalize-vk.js
// ---------------------------------------------------------------------------
return $input.all().map((item) => ({
  json: normalizeVkEvent(item.json.body !== undefined ? item.json.body : item.json),
}));

/**
 * Yandex Vision OCR response → flat text for the extraction model.
 *
 * Verified against the real responses in ocr-results/, captured from Russian
 * thermal receipts on 2026-09-03.
 *
 * The shape is deeper than it looks and has one trap: `lines` carry NO `text`
 * field. Only `words[].text` exists, so a line must be rebuilt by joining its
 * words. Reading `line.text` yields `undefined` for every line and produces an
 * empty prompt with no error anywhere.
 *
 *   results[].results[].textDetection.pages[].blocks[].lines[].words[].text
 *
 * Portable to an n8n Code node as-is — no imports, no Node built-ins.
 */

'use strict';

/** Words below this confidence are kept but marked, so the model can discount them. */
const LOW_CONFIDENCE = 0.6;

function asArray(v) {
  return Array.isArray(v) ? v : [];
}

/**
 * Rebuild one line's text from its words.
 * Vision returns words in reading order, so a plain join is correct; sorting by
 * boundingBox would reorder correctly-ordered output on skewed thermal paper.
 */
function lineText(line) {
  return asArray(line && line.words)
    .map((w) => (w && typeof w.text === 'string' ? w.text : ''))
    .filter(Boolean)
    .join(' ')
    .trim();
}

/** Mean word confidence for a line, 0 when the line has no scored words. */
function lineConfidence(line) {
  const scores = asArray(line && line.words)
    .map((w) => (w && typeof w.confidence === 'number' ? w.confidence : null))
    .filter((c) => c !== null);
  if (scores.length === 0) return 0;
  return scores.reduce((a, b) => a + b, 0) / scores.length;
}

/**
 * @param {object} response - raw Vision batchAnalyze JSON
 * @returns {{text: string, lines: Array<{text: string, confidence: number}>, pages: number, lowConfidenceLines: number}}
 */
function ocrToText(response) {
  const lines = [];

  for (const outer of asArray(response && response.results)) {
    for (const inner of asArray(outer && outer.results)) {
      const pages = asArray(inner && inner.textDetection && inner.textDetection.pages);
      for (const page of pages) {
        for (const block of asArray(page && page.blocks)) {
          for (const line of asArray(block && block.lines)) {
            const text = lineText(line);
            if (!text) continue;
            lines.push({ text, confidence: lineConfidence(line) });
          }
        }
      }
    }
  }

  return {
    text: lines.map((l) => l.text).join('\n'),
    lines,
    pages: countPages(response),
    lowConfidenceLines: lines.filter((l) => l.confidence < LOW_CONFIDENCE).length,
  };
}

function countPages(response) {
  let n = 0;
  for (const outer of asArray(response && response.results)) {
    for (const inner of asArray(outer && outer.results)) {
      n += asArray(inner && inner.textDetection && inner.textDetection.pages).length;
    }
  }
  return n;
}

/**
 * Did OCR produce enough to be worth sending to a model?
 *
 * A blurred or dark photo comes back as a handful of junk lines, not as an
 * error. Routing that to the model wastes tokens and invites a hallucinated
 * receipt. Below this bar the message goes to manual review with an honest
 * reason — never to an automated rejection.
 */
function isUsable(result) {
  if (!result || !result.text) return { ok: false, reason: 'OCR вернул пустой текст' };
  if (result.lines.length < 3) {
    return { ok: false, reason: `OCR распознал только ${result.lines.length} строк(и)` };
  }
  if (!/\d/.test(result.text)) {
    return { ok: false, reason: 'В распознанном тексте нет ни одной цифры' };
  }
  return { ok: true };
}

// ---------------------------------------------------------------------------
//   source: builds/01-receipt-bot/ocr-text.js
// ---------------------------------------------------------------------------
const envelope = $('Normalize VK Event').first().json;

return $input.all().map((item) => {
  const flat = ocrToText(item.json);
  const usable = isUsable(flat);
  return {
    json: {
      ...envelope,
      receipt_text: flat.text,
      ocr_lines: flat.lines.length,
      ocr_low_confidence_lines: flat.lowConfidenceLines,
      ocr_usable: usable.ok,
      ocr_reason: usable.ok ? '' : usable.reason,
    },
  };
});

/**
 * OCR lookalike repair for Russian thermal-print receipts.
 *
 * Yandex Vision confuses Cyrillic letters with digits in receipt fonts.
 * Observed on real slips from ООО «Рафаэль» (Samara, 25.08.2026):
 *   "З'980.00 РУБ"   -> digit 3 read as Cyrillic З
 *   "ООО РАФАЗЛЬ"    -> Э read as З (text — must NOT be "repaired")
 *
 * DESIGN RULE: repair is applied ONLY to typed numeric fields (amount, date,
 * ИНН, card mask, terminal/auth ids). Free text — vendor names, addresses,
 * cashier names — goes through normalizeText(), which never touches
 * characters. This is what keeps ЗАО from becoming 3АО and ООО from becoming 000.
 *
 * Three guards, each sufficient on its own:
 *   1. Field typing — text fields never reach the repair path at all.
 *   2. Already-valid tokens are returned untouched. Repair only ever runs on
 *      a token that FAILED its pattern, so a value that already parses can
 *      never be silently altered.
 *   3. A token with no real ASCII digit is refused outright. "ЗАО" and "ООО"
 *      have none, so they can never be coerced into "3АО" / "000".
 *
 * Anything that cannot be repaired into a valid value returns a review record
 * ({ ok: false, reason }) — never a zero, never a silent drop, never an
 * automated rejection.
 *
 * Portable to an n8n Code node as-is (no imports, no Node built-ins).
 */

'use strict';

/**
 * Cyrillic/Latin glyphs → digits. Deliberately conservative: every entry here
 * is a substitution actually seen in RU thermal-receipt OCR. Adding speculative
 * pairs widens the chance of "repairing" a genuinely different value into a
 * plausible-but-wrong one, which is worse than a clean parse failure.
 */
const DIGIT_LOOKALIKES = {
  З: '3', з: '3', Э: '3',
  О: '0', о: '0', O: '0', o: '0',
  І: '1', I: '1', l: '1', '|': '1',
  Ч: '4',
  б: '6', Б: '6',
  S: '5', s: '5',
};

const AMOUNT_RE = /^\d{1,3}(?:['’  ]\d{3})*[.,]\d{2}$|^\d+[.,]\d{2}$/;
const DATE_RE = /^(\d{2})\.(\d{2})\.(\d{2}|\d{4})$/;
const ISO_DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
const INN_RE = /^\d{10}$|^\d{12}$/;
const CARD_MASK_RE = /^\*{2,6}\d{4}$/;
const ID_RE = /^\d{4,20}$/;

/** Map lookalike glyphs to digits. Internal — never call this on free text. */
function mapGlyphs(token) {
  let out = '';
  for (const ch of token) out += DIGIT_LOOKALIKES[ch] || ch;
  return out;
}

/**
 * Core repair primitive. Returns the token if it already matches, else attempts
 * a single glyph-mapped repair, else null (caller routes to manual review).
 */
function repairToken(raw, pattern) {
  if (typeof raw !== 'string') return null;
  const token = raw.trim();
  if (!token) return null;

  // Guard 2: already valid — return untouched, never "repair" a good value.
  if (pattern.test(token)) return { value: token, repaired: false };

  // Guard 3: no real digit anywhere means this is not a numeric token.
  // Kills "ЗАО", "ООО", "ЗЗЗ" before any substitution can happen.
  if (!/[0-9]/.test(token)) return null;

  const candidate = mapGlyphs(token);
  if (candidate === token) return null; // nothing to repair; genuinely malformed
  if (pattern.test(candidate)) return { value: candidate, repaired: true };

  return null;
}

function review(field, raw, reason) {
  return { ok: false, field, raw, reason };
}

/** Free text — vendor, address, cashier. NO character substitution, ever. */
function normalizeText(raw) {
  if (typeof raw !== 'string') return '';
  return raw.replace(/\s+/g, ' ').trim();
}

/**
 * Strip receipt decoration from around an amount, before any repair runs.
 *
 * Real slips (ООО «Рафаэль», 25.08.2026) print totals as "=10480.00" and
 * "67'376.00 РУБ", never as a bare number. The patterns are anchored, so the
 * decoration alone is enough to fail every real total.
 *
 * ORDER MATTERS: this must run BEFORE glyph repair. "РУБ" glyph-maps to "РУ6",
 * which would turn a strippable suffix into permanent garbage.
 *
 * Only a leading "=" and a trailing currency word are removed. Nothing else —
 * a looser strip would let genuinely malformed values through as plausible
 * numbers, which is worse than a clean parse failure.
 */
function stripAmountNoise(raw) {
  if (typeof raw !== 'string') return raw;
  return raw
    .trim()
    .replace(/^[=＝]+\s*/, '')
    .replace(/\s*(?:РУБ(?:ЛЕЙ)?\.?|RUB|руб\.?|₽)\s*$/iu, '')
    .trim();
}

/** "З'980.00 РУБ" -> 3980.00 (repaired). "=10480.00" -> 10480.00 (clean). */
function parseAmount(raw) {
  const r = repairToken(stripAmountNoise(raw), AMOUNT_RE);
  if (!r) return review('amount', raw, 'unparseable_amount');
  const numeric = r.value.replace(/['’  ]/g, '').replace(',', '.');
  const value = Number(numeric);
  if (!Number.isFinite(value)) return review('amount', raw, 'non_finite_amount');
  return { ok: true, field: 'amount', value, repaired: r.repaired, raw };
}

/**
 * Normalise the separators a receipt or a model might use.
 *
 * The prompt asks for ДД.ММ.ГГГГ, but a model can still answer "2026-08-25" or
 * "25/08/2026". Rejecting those would raise a review flag on a date that was
 * read perfectly — a false failure, which is worse than a real one because it
 * trains the user to ignore the warnings.
 *
 * Runs BEFORE glyph repair, for the same reason amount noise does: a separator
 * is not a digit and must not be fed to the lookalike map.
 */
function stripDateNoise(raw) {
  if (typeof raw !== 'string') return raw;
  return raw.trim().replace(/[\/\u2013\u2014]/g, '.');
}

/** "25.08.2026" / "25.08.26" / "2026-08-25" -> ISO, with calendar validation. */
function parseDate(raw, { pivot = 70 } = {}) {
  const cleaned = stripDateNoise(raw);

  // ISO first — "2026-08-25" would otherwise be mangled by separator swapping.
  const iso = typeof cleaned === 'string' ? cleaned.match(ISO_DATE_RE) : null;
  if (iso) {
    return buildDate(Number(iso[3]), Number(iso[2]), Number(iso[1]), false, raw);
  }

  const r = repairToken(cleaned, DATE_RE);
  if (!r) return review('date', raw, 'unparseable_date');

  const m = r.value.match(DATE_RE);
  const day = Number(m[1]);
  const month = Number(m[2]);
  let year = Number(m[3]);
  if (m[3].length === 2) year += year <= pivot ? 2000 : 1900;

  return buildDate(day, month, year, r.repaired, raw);
}

/** Shared calendar validation. Rejects 31.02 rather than rolling it into March. */
function buildDate(day, month, year, repaired, raw) {
  const d = new Date(Date.UTC(year, month - 1, day));
  if (
    d.getUTCFullYear() !== year ||
    d.getUTCMonth() !== month - 1 ||
    d.getUTCDate() !== day
  ) {
    return review('date', raw, 'invalid_calendar_date');
  }
  return { ok: true, field: 'date', value: d.toISOString().slice(0, 10), repaired, raw };
}

/** Official ФНС control-digit algorithm for 10- and 12-digit ИНН. */
function innChecksumValid(inn) {
  const d = inn.split('').map(Number);
  const check = (coeffs, upTo) => {
    let sum = 0;
    for (let i = 0; i < coeffs.length; i++) sum += coeffs[i] * d[i];
    return (sum % 11) % 10 === d[upTo];
  };
  if (inn.length === 10) {
    return check([2, 4, 10, 3, 5, 9, 4, 6, 8], 9);
  }
  return (
    check([7, 2, 4, 10, 3, 5, 9, 4, 6, 8], 10) &&
    check([3, 7, 2, 4, 10, 3, 5, 9, 4, 6, 8], 11)
  );
}

/** ИНН — repaired, then checksum-validated. A bad checksum goes to review. */
function parseInn(raw) {
  const r = repairToken(raw, INN_RE);
  if (!r) return review('inn', raw, 'unparseable_inn');
  if (!innChecksumValid(r.value)) return review('inn', raw, 'inn_checksum_failed');
  return { ok: true, field: 'inn', value: r.value, repaired: r.repaired, raw };
}

/** "****5353" -> last 4 digits. Never returns a full PAN. */
/**
 * Terminals print a single trailing status letter after the mask ("****5353 W").
 * Only one trailing letter, separated by space, is removed — anything more
 * permissive would swallow real data.
 */
function stripCardNoise(raw) {
  if (typeof raw !== 'string') return raw;
  return raw.trim().replace(/\s+[A-ZА-Я]$/iu, '').trim();
}

function parseCardMask(raw) {
  const r = repairToken(stripCardNoise(raw), CARD_MASK_RE);
  if (!r) return review('card_mask', raw, 'unparseable_card_mask');
  return {
    ok: true,
    field: 'card_mask',
    value: r.value.slice(-4),
    repaired: r.repaired,
    raw,
  };
}

/** TID / MID / RRN / КОД.АВТ — plain digit ids. */
function parseId(raw, field = 'id') {
  const r = repairToken(raw, ID_RE);
  if (!r) return review(field, raw, 'unparseable_id');
  return { ok: true, field, value: r.value, repaired: r.repaired, raw };
}

/**
 * Parse a whole extracted receipt. `fields` is the field-typed output of your
 * extraction step — the typing is what routes each value to the right parser
 * and keeps text away from the repair path entirely.
 *
 * Returns { ok, data, repairs, review } — `review` non-empty means a human
 * looks at it before anything is written to the CRM.
 */
function parseReceipt(fields) {
  const PARSERS = {
    amount: parseAmount,
    date: parseDate,
    inn: parseInn,
    card_mask: parseCardMask,
    tid: (v) => parseId(v, 'tid'),
    mid: (v) => parseId(v, 'mid'),
    rrn: (v) => parseId(v, 'rrn'),
    auth_code: (v) => parseId(v, 'auth_code'),
  };
  const TEXT_FIELDS = new Set(['vendor', 'address', 'cashier', 'raw_text']);

  const data = {};
  const repairs = [];
  const needsReview = [];

  for (const [key, raw] of Object.entries(fields || {})) {
    if (TEXT_FIELDS.has(key)) {
      data[key] = normalizeText(raw); // never character-substituted
      continue;
    }
    const parser = PARSERS[key];
    if (!parser) {
      data[key] = raw; // unknown field — pass through untouched
      continue;
    }
    const result = parser(raw);
    if (result.ok) {
      data[key] = result.value;
      if (result.repaired) repairs.push({ field: key, raw, value: result.value });
    } else {
      data[key] = null;
      needsReview.push(result);
    }
  }

  return { ok: needsReview.length === 0, data, repairs, review: needsReview };
}

// ---------------------------------------------------------------------------
//   source: builds/01-receipt-bot/normalize.js
//
// The model extracts; this validates. Anything that fails its pattern becomes a
// review record with a stated reason — never a zero, never a silent drop, never
// an automated rejection.
// ---------------------------------------------------------------------------
const envelope = $('Normalize VK Event').first().json;

/** The model is asked for JSON but can still wrap it in prose or a fence. */
function parseModelJson(raw) {
  if (raw && typeof raw === 'object') return raw;
  const text = String(raw == null ? '' : raw);
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1] : text;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1));
  } catch (e) {
    return null;
  }
}

return $input.all().map((item) => {
  const src = item.json;
  const extracted = parseModelJson(src.text !== undefined ? src.text : src);

  if (!extracted) {
    return { json: {
      ...envelope,
      needs_review: true,
      review_reason: 'Модель вернула не-JSON — проверьте вручную',
      vendor: '', expense_date: null, total: null, currency: 'RUB',
      category: 'прочее', confidence: 0,
      raw_text: String(src.text == null ? '' : src.text).slice(0, 2000),
    }};
  }

  // Several slips in one photo is a real case (seen in the test corpus). Never
  // silently log one of them as "the" expense.
  if (extracted.multiple_receipts === true) {
    return { json: {
      ...envelope,
      needs_review: true,
      review_reason: 'На фото несколько чеков — отправьте по одному',
      vendor: '', expense_date: null, total: null, currency: 'RUB',
      category: 'прочее', confidence: 0,
      raw_text: (extracted.raw_text || '').slice(0, 2000),
    }};
  }

  const checked = parseReceipt({
    vendor: extracted.vendor || '',
    amount: extracted.total == null ? '' : String(extracted.total),
    date: extracted.expense_date || '',
  });

  const reasons = checked.review.map((r) => `${r.field}: ${r.reason}`);
  const confidence = Number(extracted.confidence);

  return { json: {
    ...envelope,
    vendor: checked.data.vendor || '',
    expense_date: checked.data.date || null,
    total: checked.data.amount == null ? null : checked.data.amount,
    currency: extracted.currency || 'RUB',
    category: extracted.category || 'прочее',
    confidence: Number.isFinite(confidence) ? confidence : 0,
    needs_review: reasons.length > 0,
    review_reason: reasons.join('; '),
    repairs: checked.repairs.map((r) => `${r.field}: ${r.raw} -> ${r.value}`).join('; '),
    raw_text: (extracted.raw_text || '').slice(0, 2000),
  }};
});

